    "builtForEventsSubtitle": "Kami membina Event Game Studio berasaskan cabaran sebenar produksi acara—tempoh persediaan singkat, Wi-Fi terhad, dan jangkaan tinggi klien.",
    "benefitZeroCodingTitle": "Sifar Pengekodan",
