    "benefitWhiteLabelTitle": "Label Putih (White Label)",
    "benefitWhiteLabelDesc": "Persembahan bersih sepenuhnya dengan visual jenama klien anda—tanpa tera air atau lencana platform pihak ketiga.",
    "benefitSupportTitle": "Sokongan Acara Langsung",
    "benefitSupportDesc": "Bantuan siap sedia secara langsung melalui WhatsApp dan e-mel sepanjang waktu acara anda berlangsung.",
    "faqBadge": "Soalan Lazim",
    "faqTitle": "Soalan Lazim (FAQ)",
    "faqSubtitle": "Jawapan jelas mengenai pelesenan, penyesuaian, persediaan perkakasan, dan pelaksanaan langsung.",
    "faqQ1": "Apakah yang termasuk dalam setiap lesen acara?",
    "faqA1": "Setiap lesen merangkumi akses penuh enjin permainan, penyesuaian tema di Studio Tema visual kami, permainan tetamu tanpa had, papan pendahulu langsung untuk paparan pentas, hari persediaan percuma 24 jam untuk raptai, serta sokongan acara.",
    "faqQ2": "Adakah pengunjung perlu memuat turun aplikasi untuk bermain?",
    "faqA2": "Tidak. Semua permainan dimainkan terus di dalam pelayar web biasa (Safari, Chrome, Edge) melalui imbasan kod QR atau pautan web. Tiada muat turun aplikasi atau log masuk diperlukan untuk pengunjung.",
    "faqQ3": "Bolehkah saya menggunakan logo, produk, dan penjenamaan sendiri?",
    "faqA3": "Ya. Anda boleh memuat naik logo tersuai, pemandangan latar belakang, barangan kutipan mata (seperti produk runcit sebenar anda), halangan penalti, skrin mula, dan skrin keputusan tanpa sebarang tera air platform.",
    "faqQ4": "Berapa lamakah saya boleh menjalankan sesuatu acara?",
    "faqA4": "Anda boleh melesenkan acara dari 1 hari kalendar sehingga 30 hari secara layan diri terus di platform, atau meminta sebut harga tersuai untuk jerayawara jangka panjang dan aktivasi jelajah.",
    "faqQ5": "Bagaimanakah struktur harga acara dikira?",
    "faqA5": "Harga adalah berasaskan tempoh kalendar (termasuk tarikh mula dan tamat dalam zon masa UTC+8). 1 Hari ialah RM1,400, 2 Hari ialah RM1,900, 3 Hari ialah RM2,200, 4–7 Hari ialah RM2,800, 8–14 Hari ialah RM4,500, 15–30 Hari ialah RM7,500, dan 31+ hari melalui sebut harga tersuai.",
    "faqQ6": "Bolehkah saya memaparkan permainan dan papan pendahulu di dinding LED besar?",
    "faqA6": "Ya! Sambungkan mana-mana komputer riba yang menjalankan Chrome atau Edge melalui HDMI ke pemproses LED atau penukar video anda, tekan Skrin Penuh, dan nikmati grafik 60 FPS serta kemas kini skor langsung di skrin besar.",
    "faqQ7": "Bolehkah ramai pengunjung bermain serentak menggunakan kod QR?",
    "faqA7": "Ya. Ratusan pengunjung boleh mengimbas kod QR acara dengan telefon pintar mereka dan bermain serentak tanpa menghalang antara satu sama lain atau memperlahankan papan pendahulu pentas.",
    "faqQ8": "Bagaimanakah cara untuk mencipta dan menguji acara?",
    "faqA8": "Cipta ruang kerja percuma di Event Game Studio, pilih enjin permainan, muat naik aset anda, dan uji dalam simulator pratonton peribadi. Hari persediaan 24 jam membuka ujian raptai penuh sebelum hari acara bermula.",
    "finalCtaHeadline": "Bersedia untuk Menjadikan Acara Anda Lebih Interaktif?",
    "finalCtaSubtitle": "Sertai agensi acara, pengurus jenama, dan penganjur korporat yang mencipta pengalaman interaktif yang tidak dapat dilupakan.",
